"""Tasks tab — interactive view of the PA's actions.md."""

from __future__ import annotations

import json
import logging
import tkinter as tk
import webbrowser
from datetime import date
from functools import partial
from pathlib import Path
from tkinter import ttk
from typing import Any, Callable

from personal_assistant_dashboard.config import (
    BG_OUTPUT,
    BG_WINDOW,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    COLOR_DECLINED,
    COLOR_DISABLED_FG,
    COLOR_LINK,
    COLOR_SECTION_HEADER,
    FG_DIM,
    FG_TEXT,
    PAD,
    TASKS_POLL_INTERVAL_MS,
)
from personal_assistant_dashboard.tasks_md import (
    Task,
    bump_target,
    first_url,
    move_task,
    parse_tasks,
    section_label,
    set_done,
    split_links,
)
from personal_assistant_dashboard.utils import atomic_write_json

logger = logging.getLogger(__name__)

_NO_SECTION = "Unsectioned"

# BMP only — Tkinter on Linux cannot render U+10000 and above.
DONE_GLYPH = "×"  # ×
RESTORE_GLYPH = "+"
UP_GLYPH = "▲"  # ▲
DOWN_GLYPH = "▼"  # ▼
COLLAPSED_GLYPH = "▸"  # ▸
EXPANDED_GLYPH = "▾"  # ▾


class TasksTab:
    """Tasks tab rendering actions.md with per-row done/restore buttons."""

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        tasks_path: Path,
        state_path: Path,
        notebook: ttk.Notebook | None = None,
        console_log: Callable[..., None] | None = None,
        notify_tab: Callable[[str], None] | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._tasks_path = tasks_path
        self._state_path = state_path
        self._notebook = notebook
        self._console_log = console_log
        self._notify_tab = notify_tab
        self._tasks: list[Task] = []
        self._seen: set[str] = set()
        self._collapsed: set[str] = set()
        self._mtime = 0.0
        self._rendered_day = date.today()
        self._hit_seq = 0
        self._show_done_var = tk.BooleanVar(value=False)
        self._font_body = "app_body"
        self._font_heading = "app_heading"
        self._load_seen()
        self._load_collapsed()
        self._build()
        self.refresh(alert=False)
        self._schedule_poll()

    # --- construction ---

    def _build(self) -> None:
        top = tk.Frame(self._parent, bg=BG_WINDOW)
        top.pack(fill=tk.X, pady=(0, PAD))

        tk.Button(
            top,
            text="↻",
            command=self.refresh,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=self._font_body,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=4,
        ).pack(side=tk.LEFT, padx=(PAD, 4))

        self._done_text_var = tk.StringVar(value="Done:0")
        self._done_btn = tk.Checkbutton(
            top,
            textvariable=self._done_text_var,
            variable=self._show_done_var,
            command=self._on_done_toggle,
            bg=BG_WINDOW,
            fg=FG_DIM,
            selectcolor=BG_WINDOW,
            activebackground=BG_WINDOW,
            activeforeground=FG_TEXT,
            font=self._font_body,
            relief=tk.FLAT,
            cursor="hand2",
            indicatoron=False,
            padx=6,
        )
        self._done_btn.pack(side=tk.LEFT, padx=(PAD, 0))

        self._status_var = tk.StringVar(value="Loading...")
        tk.Label(
            top,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=self._font_body,
        ).pack(side=tk.RIGHT, padx=(0, PAD))

        container = tk.Frame(self._parent, bg=BG_OUTPUT)
        container.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=(0, PAD))

        self._text = tk.Text(
            container,
            bg=BG_OUTPUT,
            fg=FG_TEXT,
            font=self._font_body,
            wrap=tk.WORD,
            state=tk.DISABLED,
            highlightthickness=0,
            borderwidth=0,
            cursor="arrow",
        )
        scrollbar = tk.Scrollbar(container, command=self._text.yview)
        self._text.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        self._text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        def _scroll_text(event: Any) -> str:
            self._text.yview_scroll(-1 if event.num == 4 else 1, "units")
            return "break"

        self._text.bind("<Button-4>", _scroll_text)
        self._text.bind("<Button-5>", _scroll_text)

        self._text.tag_configure(
            "section", foreground=COLOR_SECTION_HEADER, font=self._font_heading
        )
        self._text.tag_configure("dim", foreground=FG_DIM)
        self._text.tag_configure("done", foreground=COLOR_DECLINED, lmargin2=28)
        self._text.tag_configure("detail", foreground=FG_DIM, lmargin1=64, lmargin2=64)
        self._text.tag_configure("task", lmargin2=64)
        self._text.tag_configure("disabled", foreground=COLOR_DISABLED_FG)

    # --- data ---

    def refresh(self, *, alert: bool = True) -> None:
        """Reparse actions.md and redraw."""
        try:
            content = self._tasks_path.read_text(encoding="utf-8")
            self._mtime = self._tasks_path.stat().st_mtime
        except OSError:
            self._tasks = []
            self._render()
            self._status_var.set(f"{self._tasks_path.name} not found")
            return
        self._tasks = parse_tasks(content)
        new = [t for t in self._tasks if not t.done and t.key not in self._seen]
        had_seen = bool(self._seen)
        self._seen = {t.key for t in self._tasks}
        self._save_seen()
        self._render()
        if alert and had_seen and new:
            if self._notify_tab:
                self._notify_tab("Tasks")
            for task in new:
                self._log(
                    f"[Tasks] new: {task.text}",
                    "warning",
                    link=first_url(task),
                )

    def _schedule_poll(self) -> None:
        def _tick() -> None:
            try:
                mtime = self._tasks_path.stat().st_mtime
            except OSError:
                mtime = 0.0
            if mtime != self._mtime:
                self.refresh()
            elif self._rendered_day != date.today():
                # The dashboard runs overnight. Arrow targets are computed at
                # render, so a view drawn yesterday would bump a task into
                # the past. Redraw on the date rolling over.
                self._render()
            self._schedule_poll()

        self._root.after(TASKS_POLL_INTERVAL_MS, _tick)

    def _log(
        self,
        message: str,
        tag: str = "info",
        link: str = "",
        link_label: str = "",
    ) -> None:
        if self._console_log:
            self._console_log(message, tag, link, link_label)
        else:
            logger.warning(message)

    # --- rendering ---

    def _on_done_toggle(self) -> None:
        self._done_btn.configure(
            fg=COLOR_DECLINED if self._show_done_var.get() else FG_DIM
        )
        self._render()

    def _render(self) -> None:
        show_done = self._show_done_var.get()
        self._text.configure(state=tk.NORMAL)
        self._text.delete("1.0", tk.END)
        self._hit_seq = 0
        today = date.today()
        self._rendered_day = today

        visible = [t for t in self._tasks if t.done == show_done]
        sections: dict[str, list[Task]] = {}
        for task in visible:
            sections.setdefault(task.section or _NO_SECTION, []).append(task)

        if not visible:
            self._text.insert(tk.END, "  Nothing here\n", "dim")
        for name, tasks in sections.items():
            collapsed = name in self._collapsed
            toggle = partial(self._toggle_collapsed, name)
            self._insert_hit(
                COLLAPSED_GLYPH if collapsed else EXPANDED_GLYPH,
                toggle,
                "section",
                COLOR_SECTION_HEADER,
            )
            label = section_label(name, today)
            self._insert_hit(
                f" {label} ({len(tasks)})", toggle, "section", COLOR_SECTION_HEADER
            )
            self._text.insert(tk.END, "\n")
            if not collapsed:
                for task in tasks:
                    self._render_row(task, today)
            self._text.insert(tk.END, "\n")

        self._text.configure(state=tk.DISABLED)
        self._update_status()

    def _render_row(self, task: Task, today: date) -> None:
        base = "done" if task.done else "task"
        if task.done:
            self._insert_hit(
                RESTORE_GLYPH,
                partial(self._set_done, task, False),
                base,
                COLOR_DECLINED,
            )
        else:
            self._insert_hit(
                DONE_GLYPH, partial(self._set_done, task, True), base, FG_DIM
            )
            for glyph, direction in ((UP_GLYPH, -1), (DOWN_GLYPH, 1)):
                target = bump_target(task.section, direction, today)
                self._text.insert(tk.END, " ", base)
                if target is None:
                    # Today is the floor — nothing to move to.
                    self._text.insert(tk.END, glyph, (base, "disabled"))
                    continue
                self._insert_hit(glyph, partial(self._move, task, target), base, FG_DIM)

        self._text.insert(tk.END, "  ", base)
        for display, url in split_links(task.text):
            if url:
                self._insert_link(display, url, base)
            else:
                self._text.insert(tk.END, display, base)
        self._text.insert(tk.END, "\n")

        for line in task.detail:
            for display, url in split_links(line):
                if url:
                    self._insert_link(display, url, "detail")
                else:
                    self._text.insert(tk.END, display, "detail")
            self._text.insert(tk.END, "\n")

    def _insert_hit(
        self,
        display: str,
        command: Callable[[], None],
        base_tag: str,
        color: str,
    ) -> None:
        """Insert clickable text.

        Tagged text rather than an embedded ``tk.Button``: a button is 24px
        tall on a 20px line, so a row of them dwarfs the task text, and a
        long actions.md would carry one widget per control.
        """
        self._hit_seq += 1
        tag = f"hit_{self._hit_seq}"
        self._text.insert(tk.END, display, (base_tag, tag))
        self._text.tag_configure(tag, foreground=color)

        def _click(_event: Any) -> None:
            command()

        self._text.tag_bind(tag, "<Button-1>", _click)
        self._text.tag_bind(
            tag,
            "<Enter>",
            lambda e: (
                self._text.configure(cursor="hand2"),
                self._text.tag_configure(tag, foreground=COLOR_LINK),
            ),
        )
        self._text.tag_bind(
            tag,
            "<Leave>",
            lambda e: (
                self._text.configure(cursor="arrow"),
                self._text.tag_configure(tag, foreground=color),
            ),
        )

    def _insert_link(self, display: str, url: str, base_tag: str) -> None:
        self._hit_seq += 1
        tag = f"link_{self._hit_seq}"
        self._text.insert(tk.END, display, (base_tag, tag))
        self._text.tag_configure(tag, foreground=COLOR_LINK, underline=True)

        def _open(_event: Any, u: str = url) -> None:
            webbrowser.open(u)

        self._text.tag_bind(tag, "<Button-1>", _open)
        self._text.tag_bind(
            tag, "<Enter>", lambda e: self._text.configure(cursor="hand2")
        )
        self._text.tag_bind(
            tag, "<Leave>", lambda e: self._text.configure(cursor="arrow")
        )

    def _update_status(self) -> None:
        open_count = sum(1 for t in self._tasks if not t.done)
        done_count = len(self._tasks) - open_count
        self._done_text_var.set(f"Done:{done_count}")
        self._status_var.set(f"{open_count} open")
        if self._notebook is not None:
            try:
                self._notebook.tab(self._parent, text=f"Tasks:{open_count}")
            except tk.TclError:
                pass

    # --- edits ---

    def _set_done(self, task: Task, done: bool) -> None:
        self._edit(lambda: set_done(self._tasks_path, task, done))

    def _move(self, task: Task, target: date) -> None:
        self._edit(
            lambda: move_task(self._tasks_path, task, target, today=date.today())
        )

    def _edit(self, write: Callable[[], bool]) -> None:
        """Run a write against actions.md, then reload from what landed."""
        try:
            written = write()
        except OSError:
            logger.exception("actions.md write failed")
            self._log("[Tasks] could not write actions.md, see logs", "error")
            return
        if not written:
            self._log(
                "[Tasks] actions.md changed underneath — reloaded, try again",
                "warning",
            )
        self.refresh(alert=False)

    # --- view state ---

    def _toggle_collapsed(self, section: str) -> None:
        if section in self._collapsed:
            self._collapsed.discard(section)
        else:
            self._collapsed.add(section)
        self._save_collapsed()
        self._render()

    def _load_collapsed(self) -> None:
        path = self._state_path / "collapsed_sections.json"
        try:
            with open(path) as f:
                self._collapsed = set(json.load(f))
        except (OSError, json.JSONDecodeError):
            pass

    def _save_collapsed(self) -> None:
        # ponytail: keyed by heading text, so a collapsed date section is
        # forgotten once that date rolls off. The named buckets are the ones
        # worth remembering, and their titles are stable.
        try:
            atomic_write_json(
                self._state_path / "collapsed_sections.json", sorted(self._collapsed)
            )
        except OSError:
            pass

    # --- seen-task state ---

    def _load_seen(self) -> None:
        path = self._state_path / "seen_tasks.json"
        try:
            with open(path) as f:
                self._seen = set(json.load(f))
        except (OSError, json.JSONDecodeError):
            pass

    def _save_seen(self) -> None:
        try:
            atomic_write_json(self._state_path / "seen_tasks.json", sorted(self._seen))
        except OSError:
            pass
